 import { supabase } from '../lib/supabase';

// ✅ The correct dynamic Checkout URL
const YOCO_CHECKOUT_URL = "https://checkout.yoco.com/checkout";
const YOCO_PUBLIC_KEY = process.env.REACT_APP_YOCO_PUBLIC_KEY;

export async function initiatePayment({
  amount,
  currency = 'ZAR',
  email,
  fullName,
  userId,
  communityId = null,
  type = 'community',
}) {
  try {
    // 1. Calculate fees
    const platformFee = type === 'community' ? amount * 0.30 : amount * 0.10;
    const creatorEarnings = type === 'community' ? amount * 0.70 : amount * 0.90;

    // 2. Create pending record in Supabase
    const { data: payment, error } = await supabase
      .from('subscription_payments')
      .insert({
        user_id: userId,
        community_id: communityId,
        amount: amount,
        currency: currency,
        platform_fee: platformFee,
        creator_earnings: creatorEarnings,
        type: type,
        status: 'pending'
      })
      .select()
      .single();

    if (error) throw error;

    // 3. Build the dynamic URL
    // Yoco accepts amount in cents (R50 = 5000)
    const amountInCents = Math.round(amount * 100);
    
    // We pass the return URL so Yoco knows where to send the user back
    const returnUrl = encodeURIComponent(`${window.location.origin}/payment/success?payment_id=${payment.id}`);
    
    // Construct the final URL
    const checkoutUrl = `${YOCO_CHECKOUT_URL}?key=${YOCO_PUBLIC_KEY}&amount=${amountInCents}&currency=${currency}&email=${encodeURIComponent(email)}&fullName=${encodeURIComponent(fullName || email)}&return_url=${returnUrl}`;

    // 4. Redirect the user
    window.location.href = checkoutUrl;

    return { success: true, paymentId: payment.id };

  } catch (error) {
    console.error('Payment error:', error);
    return { success: false, error: error.message };
  }
}
